<template>
  <div class="optimization">
    <OptimizationHeader :title="title" :name="name" :status="status" />
    <div class="optimization-table__box">
      <div class="optimization-option">
        <div class="optimization-option__title-box">
          <h3 class="optimization-option__title">Поиск записей</h3>
          <div class="optimization-option__btn-box">
            <ButtonUI
              svg="addad-t"
              text="Добавить Запись"
              buttonClass="btn--primary"
              @action="
                $router.push(
                  `/seo/seo-filters/create/new/${queryParams.section_id}`
                )
              "
            />
            <CustomTableOption
              v-model="selectRoleHeader"
              @update:model-value="selectOption"
              :btnClass="'btn--primary'"
              :options="optionsHeader"
            />
          </div>
        </div>
        <ul class="optimization-option__form">
          <li class="optimization-option__item">
            <span class="optimization-option__text">Раздел</span>
            <CustomSelect
              v-model="selectPartition"
              placeholder="Автомобили"
              :options="selectPartitions"
              @updateSort="sortCategory"
            />
          </li>
          <li class="optimization-option__item">
            <span class="optimization-option__text">ID Записи</span>
            <CustomInput
              v-model="inputId.value"
              placeholder="ID Записи"
              @update:model-value="updateFilterId"
            />
          </li>
          <li class="optimization-option__item" v-if="isActive">
            <span class="optimization-option__text">Город</span>
            <CustomSelectSearch
              v-if="!dataHistoy"
              v-model="selectedLocation"
              :options="locationOptions"
              @updateSort="sortCity"
            />
          </li>
          <li class="optimization-option__item" v-if="isActive">
            <span class="optimization-option__text">URL</span>
            <CustomInput
              v-model="inputUrl.value"
              placeholder="URL"
              @update:model-value="updateFilterUrl"
            />
          </li>
          <li class="optimization-option__item" v-if="isActive">
            <span class="optimization-option__text">H1</span>
            <CustomInput
              v-model="inputH1.value"
              placeholder="H1"
              @update:model-value="updateFilterH1"
            />
          </li>
          <li class="optimization-option__item" v-if="isActive">
            <span class="optimization-option__text">Title</span>
            <AutosTextTemplate placeholder="Отображение Title" />
            <CustomInput
              v-model="inputTitle.value"
              placeholder="Title"
              @update:model-value="updateFilterTitle"
            />
          </li>
          <li class="optimization-option__more">
            <div class="optimization-option__more-btn">
              <ButtonUI
                svg="search-svg"
                text="найти"
                buttonClass="btn--primary"
                @action="serchFilter"
              />
              <ButtonUI
                text="Сбросить"
                buttonClass="btn--second"
                @action="resetFilterValue"
              />
            </div>

            <p
              class="optimization-option__more-info"
              @click="isActive = !isActive"
            >
              еще настройки
              <img
                class="optimization-option__more-svg"
                src="@/assets/images/svg/arrow.svg"
                alt="arrow"
              />
            </p>
          </li>
        </ul>
      </div>

      <CustomTable
        :ItemRows="itemRow"
        :headerRows="headerRows"
        :pagination="pagination"
        :lineClamp="5"
        height="120px"
        @slot-clicked="handleButtonClick"
      >
        <template #slot-end="{ item, emitEvent }">
          <CustomTableOption
            v-model="selectRole"
            @update:model-value="emitEvent(selectRole, item.id)"
            :options="options"
          />
        </template>
      </CustomTable>
    </div>
  </div>
</template>

<script setup>
import { ref, onMounted } from 'vue';
import { useRouter } from 'vue-router';

import OptimizationHeader from '@/components/SEO/OptimizationHeader';

import CustomSelectSearch from '@/components/UI/CustomSelectSearch';
import ButtonUI from '@/components/UI/ButtonUI';
import CustomSelect from '@/components/UI/CustomSelect';
import CustomInput from '@/components/UI/CustomInput';
import CustomTable from '@/components/UI/CustomTable.vue';
import CustomTableOption from '@/components/UI/CustomTableOption.vue';

import { useQueryParams } from '@/composables/useQueryParams';
import { useSeoFilterTable } from '@/store/Table/seoFilterTable.js';

import { getFilterOption, getRegions } from '@/services/apiClient.js';
import {
  copySeoFilterItem,
  deletSeoFilterItem,
} from '@/services/apiTableAdmin.js';

const router = useRouter();
const seoFilterTable = useSeoFilterTable();

const selectPartition = ref({
  name: 'Автомобили',
  code: '1',
});

const selectedLocation = ref('');
const locationOptions = ref([]);

const title = ref('SEO Фильтров');
const name = ref('Иван Иванов');
const status = ref('сейчас на странице');
const isActive = ref(false);

const pagination = {
  currentPage: 1,
};
const {
  queryParams,
  loadQueryParamsFromRoute,
  updateQueryParams,
  buildQueryString,
} = useQueryParams();
const optionsHeader = [
  {
    name: 'Настройки по умолчанию',
    code: 'defol',
    error: false,
    success: false,
    svg: 'options-defolt',
    ValidateType: 'select',
  },
  {
    name: 'Найти дубликаты',
    code: 'duplicate',
    error: false,
    success: false,
    svg: 'duplicate-svg',
    ValidateType: 'select',
  },
  {
    name: 'Все пересечения',
    code: 'intersectin',
    error: false,
    success: false,
    svg: 'intersectin-svg',
    ValidateType: 'select',
  },
  {
    name: 'Читать лог',
    code: 'readLog',
    error: false,
    success: false,
    svg: 'read-log',
    ValidateType: 'select',
  },
];

const options = [
  {
    name: 'Редактировать',
    code: 'redact',
    error: false,
    success: false,
    svg: 'edit-svg',
    ValidateType: 'select',
  },
  {
    name: 'Создать копию',
    code: 'copy',
    error: false,
    success: false,
    svg: 'copy-svg',
    ValidateType: 'select',
  },
  {
    name: 'удалить страницу',
    code: 'delet',
    error: false,
    success: false,
    svg: 'delet-svg',
    ValidateType: 'select',
  },
];
const selectRoleHeader = ref({
  name: '',
  code: '',
  ValidateType: 'select',
  error: false,
  success: false,
});
const selectRole = ref({
  name: '',
  code: '',
  ValidateType: 'select',
  error: false,
  success: false,
});
const inputId = ref({
  value: '',
  placeholder: 'города',
});
const inputUrl = ref({
  value: '',
  placeholder: 'города',
});
const inputH1 = ref({
  value: '',
  placeholder: 'города',
});
const inputTitle = ref({
  value: '',
  placeholder: 'города',
});
const itemRow = ref([]);

const selectPartitions = ref(null);
const headerRows = ref([]);

const sortCity = (option) => {
  queryParams.value.city_id = option;
  updateQueryParams();
};
const sortCategory = (option) => {
  queryParams.value.section_id = option;
  updateQueryParams();
};
const updateFilterId = () => {
  queryParams.value.id = inputId.value.value;
  updateQueryParams();
};
const updateFilterUrl = () => {
  queryParams.value.url = inputUrl.value.value;
  updateQueryParams();
};
const updateFilterH1 = () => {
  queryParams.value.h1 = inputH1.value.value;
  updateQueryParams();
};
const updateFilterTitle = () => {
  queryParams.value.title = inputTitle.value.value;
  updateQueryParams();
};
const resetFilterValue = () => {
  inputId.value.value = '';
  inputUrl.value.value = '';
  inputTitle.value.value = '';
  inputH1.value.value = '';
  queryParams.value.title = inputTitle.value.value;
  queryParams.value.h1 = inputH1.value.value;
  queryParams.value.id = inputId.value.value;
  queryParams.value.url = inputUrl.value.value;
  queryParams.value.city_id = '';
  isActive.value = false;
  updateQueryParams();
};
const serchFilter = async () => {
  updateQueryParams();
  getItemRow();
  isActive.value = false;
};
const selectOption = () => {
  if (selectRoleHeader.value.code === 'readLog') {
    router.push('/seo/seo-filters/log');
  } else if (selectRoleHeader.value.code === 'intersectin') {
    router.push(
      `/seo/seo-filters/intersection?section_id=${queryParams.value.section_id}`
    );
  } else if (selectRoleHeader.value.code === 'duplicate') {
    router.push(`/seo/seo-filters/duplication`);
  }
};
const handleButtonClick = async (_, item) => {
  if (selectRole.value.code === 'redact') {
    router.push(
      `/seo/seo-filters/create/${item.id.value}/${queryParams.value.section_id}`
    );
  } else if (selectRole.value.code === 'copy') {
    const data = await copySeoFilterItem(item.id.value);
    if (data) {
      const newItem = {
        id: {
          value: data.data?.id,
          type: 'text',
          contenteditable: false,
        },
        sort: {
          value: data.data?.sort,
          type: 'text',
          contenteditable: false,
        },
        url: {
          value: data.data?.url.url,
          type: 'link',
          link: data.data?.url.url,
          contenteditable: false,
        },
        h1: {
          value: data.data?.h1,
          type: 'text',
          contenteditable: false,
        },
        title: {
          value: data.data?.title,
          type: 'text',
          contenteditable: false,
        },
        description: {
          value: data.data?.description,
          type: 'text',
          contenteditable: false,
        },
        keywords: {
          value: data.data?.keywords,
          type: 'text',
          contenteditable: false,
        },
        noIndex: {
          value: data.data?.is_no_index ? 'есть' : 'нет',
          type: 'text',
          contenteditable: false,
        },

        city: {
          value: data.data?.city?.title || '',
          type: 'text',
          contenteditable: false,
        },
        option: { slot: 'end', contenteditable: false, id: 1 },
      };
      itemRow.value.push(newItem);
    }
  } else if (selectRole.value.code === 'delet') {
    const data = await deletSeoFilterItem(item.id.value);
    if (data) {
      itemRow.value = itemRow.value.filter(
        (el) => item.id.value !== el.id.value
      );
    }
  }
};
const getItemRow = async () => {
  if (!queryParams.value.section_id) {
    queryParams.value.section_id = 1;
  }

  updateQueryParams();
  await seoFilterTable.getSeoFilterItem(buildQueryString(queryParams.value));
  // pagination.value = seoFilterTable.getPagination;
  itemRow.value = seoFilterTable.getItemRow;
};
// const handlePageChange = (newPage) => {
//   pagination.value.currentPage = newPage;
//   queryParams.value.page = newPage;
//   updateQueryParams();
//   getItemRow();
// };
const getHeaderRow = () => {
  headerRows.value = seoFilterTable.getHeaderRow;
};
const getParametrQRL = async () => {
  loadQueryParamsFromRoute();

  const data = await getFilterOption();

  selectPartitions.value = data.data.map((item) => ({
    name: item.title,
    code: item.id.toString(),
  }));
  if (queryParams.value.section_id) {
    selectPartition.value = selectPartitions.value.find(
      (el) => el.code == queryParams.value.section_id
    );
  }
};
const getlocation = async () => {
  const response = await getRegions();

  locationOptions.value = response;
};

onMounted(() => {
  getParametrQRL();
  loadQueryParamsFromRoute();
  getItemRow();
  getHeaderRow();
  getlocation();
});
</script>

<style scoped lang="scss">
.optimization {
  margin: 12px 16px;
  width: calc(100% - 32px);
  display: flex;
  flex-direction: column;
  height: calc(100vh - 20px);
  @media (max-width: 1024px) {
    width: calc(100% - 40px);
    justify-content: space-between;
    height: calc(100vh - 60px);
  }
  &-table__box {
    height: calc(100vh - 110px);
    display: flex;
    flex-direction: column;
    justify-content: space-between;
  }
  &-option {
    display: flex;
    flex-direction: column;
    justify-content: space-around;
    border-radius: 4px;
    background-color: #eef9ff;
    margin: 16px 0;
    padding: 12px 24px;
    &__form {
      display: flex;
      flex-direction: column;
      max-width: 480px;
    }

    &__btn-box {
      display: flex;
      gap: 16px;
      align-items: center;
    }
    &__title-box {
      display: flex;
      justify-content: space-between;
    }
    &__item {
      display: flex;
      align-items: center;
      margin-bottom: 16px;
      width: 100%;
    }
    &__text-box {
      display: flex;
    }
    &__text {
      color: #787878;
      font-weight: 400;
      font-size: 14px;
      min-width: 150px;
    }
    &__more {
      display: flex;
      align-items: center;
      justify-content: space-between;
      &-btn {
        display: flex;
        align-items: center;
        gap: 16px;
      }
      &-info {
        color: #3366ff;
      }
    }
  }
}
</style>
